pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(address actor, uint256 val) public {
        if (actor == address(0)) actor = address(1);

        c.Initialized();

        bool ok;
        bytes memory reason;
        vm.prank(actor);
        try c.SetMinSum(val) {
            ok = true;
            reason = "";
        } catch (bytes memory _reason) {
            ok = false;
            reason = _reason;
        }

        assertTrue(!ok && reason.length == 0);
    }
}
